r": "#0284c7"}, {"id": "manifold_outlet", "name": "\u10d2\u10d0\u10db\u10dd\u10db\u10d0\u10d5\u10d0\u10da\u10d8 \u10d9\u10dd\u10da\u10d4\u10e5\u10e2\u10dd\u10e0\u10d8 (Heated Outlet Return)", "shape": "cylinder", "position": {"x": 10, "y": 3.2, "z": 17.5}, "size": {"x": 2.2, "y": 13.6, "z": 2.2}, "rotation": 0, "rotationVec": {"x": 0, "y": 0, "z": 90}, "color": "#ea580c"}, {"id": "manifold_cover", "name": "\u10d6\u10d4\u10d3\u10d0 \u10d3\u10d0\u10db\u10ea\u10d0\u10d5\u10d8 \u10e1\u10d0\u10ee\u10e3\u10e0\u10d0\u10d5\u10d8 (Transparent Cover)", "shape": "box", "position": {"x": 10, "y": 4.8, "z": 10}, "size": {"x": 14.4, "y": 0.4, "z": 14.4}, "rotation": 0, "color": "#94a3b8"}], "environment": "Open space"}}, {"id": "trigger_start", "kind": "manual", "label": "\u10d3\u10d0\u10ec\u10e7\u10d4\u10d1\u10d8\u10e1 \u10e1\u10d8\u10d2\u10dc\u10d0\u10da\u10d8 (Run Trigger)", "position": {"x": 40, "y": -100}, "params": {}}, {"id": "heat_pulse", "kind": "temperatureChange", "label": "\u10d7\u10d4\u10e0\u10db\u10e3\u10da\u10d8 \u10d8\u10db\u10de\u10e3\u10da\u10e1\u10d8 (Heat Flux Load Pulse)", "position": {"x": 280, "y": -140}, "params": {"enabled": "On", "start": 0.2, "duration": 4, "x": 10, "y": 0.5, "z": 10, "radius": 10, "falloff": "Linear", "delta": 26.8, "rise": 0.6, "profile": "Ramp"}}, {"id": "temp_sensor", "kind": "temperature", "label": "\u10d9\u10d5\u10d0\u10dc\u10eb\u10d8\u10e1 \u10e2\u10d4\u10db\u10de\u10d4\u10e0\u10d0\u10e2\u10e3\u10e0\u10d8\u10e1 \u10d6\u10dd\u10dc\u10d3\u10d8 (Die Sensor)", "position": {"x": 280, "y": 20}, "params": {"x": 10, "y": 0.5, "z": 10, "sensitivity": 1, "bias": 0, "tau": 0.05}}, {"id": "scope_temp", "kind": "scope", "label": "\u10e2\u10d4\u10db\u10de\u10d4\u10e0\u10d0\u10e2\u10e3\u10e0\u10d8\u10e1 \u10dd\u10e1\u10ea\u10d8\u10da\u10dd\u10d2\u10e0\u10d0\u10db\u10d0 (Thermal Scope)", "position": {"x": 880, "y": -100}, "params": {}}, {"id": "node_width", "kind": "formula", "label": "\u10d0\u10e0\u10ee\u10d8\u10e1 \u10e1\u10d8\u10d2\u10d0\u10dc\u10d4 w_c (Channel Width)", "position": {"x": 40, "y": 100}, "params": {"expression": "a", "a": 0.4, "b": 0, "unit": "mm"}}, {"id": "node_fin", "kind": "formula", "label": "\u10e4\u10d0\u10e0\u10e4\u10da\u10d8\u10e1 \u10e1\u10d8\u10e1\u10e5\u10d4 w_f (Fin Thickness)", "position": {"x": 40, "y": 240}, "params": {"expression": "a", "a": 0.3, "b": 0, "unit": "mm"}}, {"id": "node_alpha", "kind": "formula", "label": "\u10d0\u10e1\u10de\u10d4\u10e5\u10e2\u10e3\u10e0\u10d8 \u10e4\u10d0\u10e0\u10d3\u10dd\u10d1\u10d0 alpha (Aspect Ratio)", "position": {"x": 40, "y": 380}, "params": {"expression": "a", "a": 6, "b": 0, "unit": ""}}, {"id": "node_vel", "kind": "formula", "label": "\u10dc\u10d0\u10d9\u10d0\u10d3\u10d8\u10e1 \u10e1\u10d8\u10e9\u10e5\u10d0\u10e0\u10d4 v (Flow Velocity)", "position": {"x": 40, "y": 520}, "params": {"expression": "a", "a": 1.2, "b": 0, "unit": "m/s"}}, {"id": "node_qflux", "kind": "formula", "label": "\u10e1\u10d8\u10d7\u10d1\u10e3\u10e0\u10d8 \u10dc\u10d0\u10d9\u10d0\u10d3\u10d8 q'''' (Heat Flux)", "position": {"x": 40, "y": 660}, "params": {"expression": "a", "a": 130, "b": 0, "unit": "W/cm\u00b2"}}, {"id": "node_dh", "kind": "formula", "label": "\u10f0\u10d8\u10d3\u10e0\u10d0\u10d5\u10da\u10d8\u10d9\u10e3\u10e0\u10d8 \u10d3\u10d8\u10d0\u10db\u10d4\u10e2\u10e0\u10d8 D_h (Hydraulic Dia)", "position": {"x": 320, "y": 240}, "params": {"expression": "(2 * a * b) / (1 + b)", "a": 0.4, "b": 6, "unit": "mm"}}, {"id": "node_dp", "kind": "formula", "label": "\u10ec\u10dc\u10d4\u10d5\u10d8\u10e1 \u10d5\u10d0\u10e0\u10d3\u10dc\u10d0 Delta P (Pressure Drop)", "position": {"x": 620, "y": 240}, "params": {"expression": "clamp(8.5 * a / (b * b) + 1.2 * a * a, 0.5, 120)", "a": 1.2, "b": 0.68, "unit": "kPa"}}, {"id": "node_rth", "kind": "formula", "label": "\u10d7\u10d4\u10e0\u10db\u10e3\u10da\u10d8 \u10ec\u10d8\u10dc\u10d0\u10e6\u10dd\u10d1\u10d0 R_th (Thermal Resistance)", "position": {"x": 320, "y": 520}, "params": {"expression": "(0.18 / sqrt(a)) * (1 / (1 + 0.15 * b)) + 0.12", "a": 1.2, "b": 6, "unit": "\u00b0C/(W/cm\u00b2)"}}, {"id": "node_delta_t", "kind": "formula", "label": "\u10e2\u10d4\u10db\u10de\u10d4\u10e0\u10d0\u10e2\u10e3\u10e0\u10d8\u10e1 \u10dc\u10d0\u10d6\u10d0\u10e0\u10d3\u10d8 Delta T (Temp Rise)", "position": {"x": 620, "y": 520}, "params": {"expression": "a * b", "a": 130, "b": 0.206, "unit": "\u00b0C"}}, {"id": "node_t_junction", "kind": "formula", "label": "\u10d9\u10d5\u10d0\u10dc\u10eb\u10d8\u10e1 \u10e2\u10d4\u10db\u10de\u10d4\u10e0\u10d0\u10e2\u10e3\u10e0\u10d0 T_junction (Junction Temp)", "position": {"x": 880, "y": 520}, "params": {"expression": "a + 25", "a": 26.8, "b": 0, "unit": "\u00b0C"}}], "edges": [{"id": "trigger_start-event-scene_coldplate-trigger", "source": "trigger_start", "sourceHandle": "event", "target": "scene_coldplate", "targetHandle": "trigger"}, {"id": "heat_pulse-effect-scene_coldplate-events", "source": "heat_pulse", "sourceHandle": "effect", "target": "scene_coldplate", "targetHandle": "events"}, {"id": "temp_sensor-sensor-scene_coldplate-sensors", "source": "temp_sensor", "sourceHandle": "sensor", "target": "scene_coldplate", "targetHandle": "sensors"}, {"id": "scene_coldplate-sensor:temp_sensor-scope_temp-ch1", "source": "scene_coldplate", "sourceHandle": "sensor:temp_sensor", "target": "scope_temp", "targetHandle": "ch1"}, {"id": "node_width-result-node_dh-a", "source": "node_width", "sourceHandle": "result", "target": "node_dh", "targetHandle": "a"}, {"id": "node_alpha-result-node_dh-b", "source": "node_alpha", "sourceHandle": "result", "target": "node_dh", "targetHandle": "b"}, {"id": "node_vel-result-node_dp-a", "source": "node_vel", "sourceHandle": "result", "target": "node_dp", "targetHandle": "a"}, {"id": "node_dh-result-node_dp-b", "source": "node_dh", "sourceHandle": "result", "target": "node_dp", "targetHandle": "b"}, {"id": "node_vel-result-node_rth-a", "source": "node_vel", "sourceHandle": "result", "target": "node_rth", "targetHandle": "a"}, {"id": "node_alpha-result-node_rth-b", "source": "node_alpha", "sourceHandle": "result", "target": "node_rth", "targetHandle": "b"}, {"id": "node_qflux-result-node_delta_t-a", "source": "node_qflux", "sourceHandle": "result", "target": "node_delta_t", "targetHandle": "a"}, {"id": "node_rth-result-node_delta_t-b", "source": "node_rth", "sourceHandle": "result", "target": "node_delta_t", "targetHandle": "b"}, {"id": "node_delta_t-result-node_t_junction-a", "source": "node_delta_t", "sourceHandle": "result", "target": "node_t_junction", "targetHandle": "a"}], "tools": []}', '[{"parameter_key": "channel_width", "node_id": "node_width", "param_key": "a", "not_in_model": false}, {"parameter_key": "fin_thickness", "node_id": "node_fin", "param_key": "a", "not_in_model": false}, {"parameter_key": "aspect_ratio", "node_id": "node_alpha", "param_key": "a", "not_in_model": false}, {"parameter_key": "flow_velocity", "node_id": "node_vel", "param_key": "a", "not_in_model": false}, {"parameter_key": "heat_flux", "node_id": "node_qflux", "param_key": "a", "not_in_model": false}]', '[{"outcome_key": "t_junction", "node_id": "node_t_junction", "port": "result", "reducer": "value", "threshold": 0.0}, {"outcome_key": "pressure_drop", "node_id": "node_dp", "port": "result", "reducer": "value", "threshold": 0.0}]', '2.2.0-0f55193', '2130027100d47d2fb7e0a3fe0bf87d497e063d0c190e0ee78ab8e69aff35f8bd', 'unvalidated', NULL, 'Conjugate heat transfer & microchannel hydraulic flow model with 3D cold plate assembly', '2026-10-16T11:06:53.906372+00:00');
