INSERT OR IGNORE INTO constraints (id, study_id, label, expression, kind, penalty, rationale, source_id, enabled, position) VALUES ('cst_05f0fd23686d44a79019', 'std_963895eb68f8499087c8', 'Workability & Fiber Dispersion Limit', 'fiber_volume_fraction + 0.1 * polymer_cement_ratio <= 3.0', 'hard', NULL, 'Prevents fiber clumping and pump line blockage during high-rise placement', NULL, 1, 1);
INSERT OR IGNORE INTO constraints (id, study_id, label, expression, kind, penalty, rationale, source_id, enabled, position) VALUES ('cst_96e767b14521455ea34c', 'std_963895eb68f8499087c8', 'Polymer Strength Degradation Cap', 'polymer_cement_ratio <= 8.5', 'hard', NULL, 'Excessive polymer dosage softens the inorganic C-S-H crystal matrix', NULL, 1, 2);
INSERT OR IGNORE INTO constraints (id, study_id, label, expression, kind, penalty, rationale, source_id, enabled, position) VALUES ('cst_ab83fb984b154b6e8d61', 'std_963895eb68f8499087c8', 'Minimum Matrix Binder Densification', 'water_binder_ratio - 0.5 * silica_fume_ratio <= 0.22', 'hard', NULL, 'Ensures sufficient pozzolanic micro-silica to consume free calcium hydroxide', NULL, 1, 3);
INSERT OR IGNORE INTO constraints (id, study_id, label, expression, kind, penalty, rationale, source_id, enabled, position) VALUES ('cst_e81b42456fa949d0b276', 'std_963895eb68f8499087c8', 'Maximum Water Content for Durability', 'water_binder_ratio <= 0.26', 'hard', NULL, 'Guarantees low capillary porosity and high freeze-thaw/carbonation resistance', NULL, 1, 4);
INSERT OR IGNORE INTO model_versions (id, study_id, version, kind, project_json, parameter_bindings_json, outcome_bindings_json, engine_version, signature, validation_status, validation_json, notes, created_at) VALUES ('mod_e4f20a602ded41098147', 'std_963895eb68f8499087c8', 1, 'flow', '{"version": 3, "name": "\u10d7\u10d5\u10d8\u10d7\u10e9\u10d0\u10db\u10e5\u10e0\u10dd\u10d1\u10d8 \u10d1\u10d4\u10e2\u10dd\u10dc\u10d8\u10e1 \u10d9\u10dd\u10db\u10de\u10dd\u10d6\u10d8\u10e2\u10d8 \u10ea\u10d0\u10d7\u10d0\u10db\u10d1\u10ef\u10d4\u10dc\u10d4\u10d1\u10d8\u10e1\u10d7\u10d5\u10d8\u10e1 (Smart Damped Cement Skyscraper)", "duration": 6, "sampleRate": 50, "nodes": [{"id": "scene_skyscraper", "kind": "scene3d", "label": "3D \u10ea\u10d0\u10d7\u10d0\u10db\u10d1\u10ef\u10d4\u10dc\u10d8\u10e1 \u10d9\u10dd\u10dc\u10e1\u10e2\u10e0\u10e3\u10e5\u10ea\u10d8\u10d0 (300m Tower Scene)", "position": {"x": 540, "y": -100}, "params": {"dimension": 3, "width": 30, "depth": 30, "height": 50, "temperature": 20, "light": 500, "amplitude": 1000, "frequency": 8, "objects": [{"id": "foundation_mat", "name": "\u10e1\u10d0\u10eb\u10d8\u10e0\u10d9\u10d5\u10da\u10d8\u10e1 \u10e0\u10d9\u10d8\u10dc\u10d0\u10d1\u10d4\u10e2\u10dd\u10dc\u10d8\u10e1 \u10e4\u10d8\u10da\u10d0 (Foundation Mat Slab)", "shape": "box", "position": {"x": 15, "y": 1, "z": 15}, "size": {"x": 24, "y": 2, "z": 24}, "rotation": 0, "color": "#334155"}, {"id": "shear_core", "name": "\u10ea\u10d4\u10dc\u10e2\u10e0\u10d0\u10da\u10e3\u10e0\u10d8 \u10ee\u10d8\u10e1\u10e2\u10d8 \u10d1\u10d8\u10e0\u10d7\u10d5\u10d8 (Central Shear Core)", "shape": "box", "position": {"x": 15, "y": 23, "z": 15}, "size": {"x": 8, "y": 42, "z": 8}, "rotation": 0, "color": "#64748b"}, {"id": "col_sw", "name": "\u10db\u10d4\u10d2\u10d0-\u10e1\u10d5\u10d4\u10e2\u10d8 SW (Mega Column SW)", "shape": "box", "position": {"x": 6.5, "y": 22, "z": 6.5}, "size": {"x": 2.2, "y": 40, "z": 2.2}, "rotation": 0, "color": "#475569"}, {"id": "col_se", "name": "\u10db\u10d4\u10d2\u10