, "position": {"x": 15, "y": 27, "z": 15}, "size": {"x": 19, "y": 0.5, "z": 19}, "rotation": 0, "color": "#94a3b8"}, {"id": "floor_slab_6", "name": "\u10e1\u10d0\u10e0\u10d7\u10e3\u10da\u10d8\u10e1 \u10d3\u10d8\u10d0\u10e4\u10e0\u10d0\u10d2\u10db\u10d0 #36 (Floor Slab L36)", "shape": "box", "position": {"x": 15, "y": 32, "z": 15}, "size": {"x": 19, "y": 0.5, "z": 19}, "rotation": 0, "color": "#94a3b8"}, {"id": "floor_slab_7", "name": "\u10e1\u10d0\u10e0\u10d7\u10e3\u10da\u10d8\u10e1 \u10d3\u10d8\u10d0\u10e4\u10e0\u10d0\u10d2\u10db\u10d0 #42 (Floor Slab L42)", "shape": "box", "position": {"x": 15, "y": 37, "z": 15}, "size": {"x": 19, "y": 0.5, "z": 19}, "rotation": 0, "color": "#94a3b8"}, {"id": "floor_slab_8", "name": "\u10e1\u10d0\u10e0\u10d7\u10e3\u10da\u10d8\u10e1 \u10d3\u10d8\u10d0\u10e4\u10e0\u10d0\u10d2\u10db\u10d0 #48 (Floor Slab L48)", "shape": "box", "position": {"x": 15, "y": 42, "z": 15}, "size": {"x": 19, "y": 0.5, "z": 19}, "rotation": 0, "color": "#94a3b8"}, {"id": "outrigger_mid", "name": "\u10e8\u10e3\u10d0\u10da\u10d4\u10d3\u10e3\u10e0\u10d8 \u10d3\u10d4\u10db\u10de\u10e4\u10d4\u10e0\u10e3\u10da\u10d8 \u10d0\u10e3\u10e2\u10e0\u10d8\u10d2\u10d4\u10e0\u10d8 (Mid-Height Damped Outrigger)", "shape": "box", "position": {"x": 15, "y": 22, "z": 15}, "size": {"x": 20, "y": 2.2, "z": 20}, "rotation": 0, "color": "#0284c7"}, {"id": "outrigger_top", "name": "\u10e1\u10d0\u10ee\u10e3\u10e0\u10d0\u10d5\u10d8\u10e1 \u10d0\u10e3\u10e2\u10e0\u10d8\u10d2\u10d4\u10e0\u10d8\u10e1 \u10e1\u10d0\u10e0\u10e2\u10e7\u10d4\u10da\u10d8 (Roof Belt Outrigger)", "shape": "box", "position": {"x": 15, "y": 42, "z": 15}, "size": {"x": 19.5, "y": 2, "z": 19.5}, "rotation": 0, "color": "#0369a1"}, {"id": "curtain_wall", "name": "\u10d0\u10d4\u10e0\u10dd\u10d3\u10d8\u10dc\u10d0\u10db\u10d8\u10d9\u10e3\u10e0\u10d8 \u10e8\u10e3\u10e8\u10d8\u10e1 \u10e4\u10d0\u10e1\u10d0\u10d3\u10d8 (Curtain Wall Envelope)", "shape": "box", "position": {"x": 15, "y": 22, "z": 15}, "size": {"x": 18.2, "y": 39.5, "z": 18.2}, "rotation": 0, "color": "#38bdf8"}, {"id": "spire_crown", "name": "\u10d0\u10e0\u10e5\u10d8\u10e2\u10d4\u10e5\u10e2\u10e3\u10e0\u10e3\u10da\u10d8 \u10e8\u10de\u10d8\u10da\u10d8 (Penthouse Spire)", "shape": "cylinder", "position": {"x": 15, "y": 46.5, "z": 15}, "size": {"x": 2, "y": 7, "z": 2}, "rotation": 0, "color": "#e2e8f0"}], "environment": "Open space"}}, {"id": "trigger_wind", "kind": "manual", "label": "\u10e5\u10d0\u10e0\u10d8\u10e1 \u10e8\u10e2\u10dd\u10e0\u10db\u10d8\u10e1 \u10d8\u10db\u10de\u10e3\u10da\u10e1\u10d8 (Wind Storm Trigger)", "position": {"x": 40, "y": -100}, "params": {}}, {"id": "wind_excitation", "kind": "vibration", "label": "\u10e5\u10d0\u10e0\u10d8\u10e1 \u10d2\u10e0\u10d8\u10d2\u10d0\u10da\u10d8\u10e1 \u10e0\u10ee\u10d4\u10d5\u10d0 (Wind Vortex Shedding)", "position": {"x": 280, "y": -140}, "params": {"enabled": "On", "start": 0.2, "duration": 0.6, "x": 15, "y": 35, "z": 15, "radius": 25, "falloff": "Linear", "amplitude": 14.5, "frequency": 0.25, "damping": 0.35, "phase": 0}}, {"id": "accel_sensor_top", "kind": "accelerometer", "label": "\u10e1\u10d0\u10ee\u10e3\u10e0\u10d0\u10d5\u10d8\u10e1 \u10d0\u10e9\u10e5\u10d0\u10e0\u10d4\u10d1\u10d8\u10e1 \u10e1\u10d4\u10dc\u10e1\u10dd\u10e0\u10d8 (Penthouse Accelerometer)", "position": {"x": 280, "y": 20}, "params": {"x": 15, "y": 42, "z": 15, "sensitivity": 1, "bias": 0, "tau": 0.01, "frequency": 0.25, "amplitude": 2}}, {"id": "scope_accel", "kind": "scope", "label": "\u10e0\u10ee\u10d4\u10d5\u10d8\u10e1 \u10d0\u10e9\u10e5\u10d0\u10e0\u10d4\u10d1\u10d8\u10e1 \u10dd\u10e1\u10ea\u10d8\u10da\u10dd\u10d2\u10e0\u10d0\u10db\u10d0 (Vibration Scope)", "position": {"x": 880, "y": -100}, "params": {}}, {"id": "node_wb", "kind": "formula", "label": "\u10ec\u10e7\u10d0\u10da-\u10e8\u10d4\u10db\u10d9\u10d5\u10e0\u10d4\u10da\u10d8\u10e1 \u10e4\u10d0\u10e0\u10d3\u10dd\u10d1\u10d0 w/b (Water-to-Binder)", "position": {"x": 40, "y": 100}, "params": {"expression": "a", "a": 0.22, "b": 0, "unit": ""}}, {"id": "node_sf", "kind": "formula", "label": "\u10db\u10d8\u10d9\u10e0\u10dd-\u10e1\u10d8\u10da\u10d8\u10ea\u10d8\u10e3\u10db\u10d8\u10e1 \u10ec\u10d8\u10da\u10d8 (Silica Fume Ratio)", "position": {"x": 40, "y": 220}, "params": {"expression": "a", "a": 0.15, "b": 0, "unit": "ratio"}}, {"id": "node_polymer", "kind": "formula", "label": "\u10d5\u10d8\u10e1\u10d9\u10dd\u10d4\u10da\u10d0\u10e1\u10e2\u10d8\u10e3\u10e0\u10d8 \u10de\u10dd\u10da\u10d8\u10db\u10d4\u10e0\u10d8 p/c (Polymer Dosage)", "position": {"x": 40, "y": 340}, "params": {"expression": "a", "a": 4.5, "b": 0, "unit": "%"}}, {"id": "node_fiber", "kind": "formula", "label": "\u10e4\u10d8\u10d1\u10e0\u10d8\u10e1 \u10db\u10dd\u10ea\u10e3\u10da\u10dd\u10d1\u10d8\u10d7\u10d8 \u10ec\u10d8\u10da\u10d8 V_f (Fiber Volume)", "position": {"x": 40, "y": 460}, "params": {"expression": "a", "a": 1.2, "b": 0, "unit": "%"}}, {"id": "node_wind_gust", "kind": "formula", "label": "\u10e5\u10d0\u10e0\u10d8\u10e1 \u10db\u10d0\u10e5\u10e1\u10d8\u10db\u10d0\u10da\u10e3\u10e0\u10d8 \u10e1\u10d8\u10e9\u10e5\u10d0\u10e0\u10d4 (Wind Gust Speed)", "position": {"x": 40, "y": 580}, "params": {"expression": "a", "a": 42, "b": 0, "unit": "m/s"}}, {"id": "node_fc_base", "kind": "formula", "label": "\u10d1\u10d0\u10d6\u10e3\u10e0\u10d8 \u10e1\u10d8\u10db\u10e2\u10d9\u10d8\u10ea\u10d4 (Matrix Base fc)", "position": {"x": 280, "y": 100}, "params": {"expression": "clamp((210 / (1 + 3.2 * a)) * (1 + 0.6 * b), 50, 180)", "a": 0.22, "b": 0.15, "unit": "MPa"}}, {"id": "node_fc_mod", "kind": "formula", "label": "\u10db\u10dd\u10d3\u10d8\u10e4\u10d8\u10d9\u10d0\u10e2\u10dd\u10e0\u10d8\u10e1 \u10d9\u10dd\u10d4\u10e4\u10d8\u10ea\u10d8\u10d4\u10dc\u10e2\u10d8 (Poly/Fiber Mod)", "position": {"x": 280, "y": 220}, "params": {"expression": "clamp(1 - 0.035 * a + 0.08 * b, 0.5, 1.3)", "a": 4.5, "b": 1.2, "unit": "factor"}}, {"id": "node_fc", "kind": "formula", "label": "\u10e1\u10d8\u10db\u10e2\u10d9\u10d8\u10ea\u10d4 \u10d9\u10e3\u10db\u10e8\u10d5\u10d0\u10d6\u10d4 f_c (Compressive Strength)", "position": {"x": 500, "y": 100}, "params": {"expression": "clamp(a * b, 45, 180)", "a": 123, "b": 0.95, "unit": "MPa"}}, {"id": "node_damping_add", "kind": "formula", "label": "\u10d3\u10d0\u10db\u10d0\u10e2\u10d4\u10d1\u10d8\u10d7\u10d8 \u10d3\u10d4\u10db\u10de\u10e4\u10d8\u10e0\u10d4\u10d1\u10d0 (Poly/Fiber Damping)", "position": {"x": 280, "y": 340}, "params": {"expression": "0.38 * a + 0.52 * b", "a": 4.5, "b": 1.2, "unit": "%"}}, {"id": "node_damping", "kind": "formula", "label": "\u10d3\u10d4\u10db\u10de\u10e4\u10d8\u10e0\u10d4\u10d1\u10d8\u10e1 \u10d9\u10dd\u10d4\u10e4\u10d8\u10ea\u10d8\u10d4\u10dc\u10e2\u10d8 zeta (Damping Ratio)", "position": {"x": 500, "y": 340}, "params": {"expression": "clamp(1.1 + a - 0.8 * b, 0.8, 6.5)", "a": 2.33, "b": 0.22, "unit": "%"}}, {"id": "node_wind_force", "kind": "formula", "label": "\u10d0\u10d4\u10e0\u10dd\u10d3\u10d8\u10dc\u10d0\u10db\u10d8\u10d9\u10e3\u10e0\u10d8 \u10e5\u10d0\u10e0\u10d8\u10e1 \u10eb\u10d0\u10da\u10d0 (Wind Load)", "position": {"x": 280, "y": 580}, "params": {"expression": "clamp(0.042 * a * a, 20, 220)", "a": 42, "b": 0, "unit": "kN"}}, {"id": "node_amplification", "kind": "formula", "label": "\u10d3\u10d8\u10dc\u10d0\u10db\u10d8\u10d9\u10e3\u10e0\u10d8 \u10d2\u10d0\u10eb\u10da\u10d8\u10d4\u10e0\u10d4\u10d1\u10d0 Q (Dynamic Amplification)", "position": {"x": 700, "y": 340}, "params": {"expression": "clamp(50 / a, 5, 55)", "a": 3.26, "b": 0, "unit": ""}}, {"id": "node_stiffness", "kind": "formula", "label": "\u10e1\u10e2\u10e0\u10e3\u10e5\u10e2\u10e3\u10e0\u10e3\u10da\u10d8 \u10e1\u10d8\u10ee\u10d8\u10e1\u10e2\u10d4 (Modal Stiffness)", "position": {"x": 700, "y": 100}, "params": {"expression": "12 + 0.35 * sqrt(a)", "a": 116.8, "b": 0, "unit": "factor"}}, {"id": "node_accel_raw", "kind": "formula", "label": "\u10d3\u10d8\u10dc\u10d0\u10db\u10d8\u10d9\u10e3\u10e0\u10d8 \u10eb\u10d0\u10da\u10d5\u10d0 (Dynamic Excitation)", "position": {"x": 700, "y": 580}, "params": {"expression": "0.2 * a * b", "a": 74.1, "b": 15.3, "unit": "force-Q"}}, {"id": "node_top_accel", "kind": "formula", "label": "\u10db\u10d0\u10e5\u10e1\u10d8\u10db\u10d0\u10da\u10e3\u10e0\u10d8 \u10d0\u10e9\u10e5\u10d0\u10e0\u10d4\u10d1\u10d0 a_peak (Top Acceleration)", "position": {"x": 920, "y": 340}, "params": {"expression": "clamp(a / b, 2, 60)", "a": 226.7, "b": 15.8, "unit": "milli-g"}}, {"id": "node_carbon_clinker", "kind": "formula", "label": "\u10d9\u10da\u10d8\u10dc\u10d9\u10d4\u10e0\u10d8\u10e1 \u10d4\u10db\u10d8\u10e1\u10d8\u10d0 (Clinker Carbon)", "position": {"x": 280, "y": 460}, "params": {"expression": "clamp(460 * (1 - 1.2 * a), 180, 500)", "a": 0.15, "b": 0, "unit": "kg CO2/m\u00b3"}}, {"id": "node_carbon_admix", "kind": "formula", "label": "\u10d3\u10d0\u10dc\u10d0\u10db\u10d0\u10e2\u10d4\u10d1\u10d8\u10e1 \u10d4\u10db\u10d8\u10e1\u10d8\u10d0 (Admixture Carbon)", "position": {"x": 500, "y": 460}, "params": {"expression": "12 * a + 25 * b", "a": 4.5, "b": 1.2, "unit": "kg CO2/m\u00b3"}}, {"id": "node_carbon", "kind": "formula", "label": "\u10dc\u10d0\u10ee\u10e8\u10d8\u10e0\u10d1\u10d0\u10d3\u10d8\u10e1 \u10d4\u10db\u10d8\u10e1\u10d8\u10d0 (Embodied Carbon)", "position": {"x": 700, "y": 460}, "params": {"expression": "clamp(a + b, 180, 580)", "a": 377.2, "b": 84, "unit": "kg CO2/m\u00b3"}}], "edges": [{"id": "trigger_wind-event-scene_skyscraper-trigger", "source": "trigger_wind", "sourceHandle": "event", "target": "scene_skyscraper", "targetHandle": "trigger"}, {"id": "wind_excitation-effect-scene_skyscraper-events", "source": "wind_excitation", "sourceHandle": "effect", "target": "scene_skyscraper", "targetHandle": "events"}, {"id": "accel_sensor_top-sensor-scene_skyscraper-sensors", "source": "accel_sensor_top", "sourceHandle": "sensor", "target": "scene_skyscraper", "targetHandle": "sensors"}, {"id": "scene_skyscraper-sensor:accel_sensor_top-scope_accel-ch1", "source": "scene_skyscraper", "sourceHandle": "sensor:accel_sensor_top", "targ