"result", "target": "node_accel_raw", "targetHandle": "a"}, {"id": "node_amplification-result-node_accel_raw-b", "source": "node_amplification", "sourceHandle": "result", "target": "node_accel_raw", "targetHandle": "b"}, {"id": "node_accel_raw-result-node_top_accel-a", "source": "node_accel_raw", "sourceHandle": "result", "target": "node_top_accel", "targetHandle": "a"}, {"id": "node_stiffness-result-node_top_accel-b", "source": "node_stiffness", "sourceHandle": "result", "target": "node_top_accel", "targetHandle": "b"}, {"id": "node_sf-result-node_carbon_clinker-a", "source": "node_sf", "sourceHandle": "result", "target": "node_carbon_clinker", "targetHandle": "a"}, {"id": "node_polymer-result-node_carbon_admix-a", "source": "node_polymer", "sourceHandle": "result", "target": "node_carbon_admix", "targetHandle": "a"}, {"id": "node_fiber-result-node_carbon_admix-b", "source": "node_fiber", "sourceHandle": "result", "target": "node_carbon_admix", "targetHandle": "b"}, {"id": "node_carbon_clinker-result-node_carbon-a", "source": "node_carbon_clinker", "sourceHandle": "result", "target": "node_carbon", "targetHandle": "a"}, {"id": "node_carbon_admix-result-node_carbon-b", "source": "node_carbon_admix", "sourceHandle": "result", "target": "node_carbon", "targetHandle": "b"}], "tools": []}', '[{"parameter_key": "water_binder_ratio", "node_id": "node_wb", "param_key": "a", "not_in_model": false}, {"parameter_key": "silica_fume_ratio", "node_id": "node_sf", "param_key": "a", "not_in_model": false}, {"parameter_key": "polymer_cement_ratio", "node_id": "node_polymer", "param_key": "a", "not_in_model": false}, {"parameter_key": "fiber_volume_fraction", "node_id": "node_fiber", "param_key": "a", "not_in_model": false}, {"parameter_key": "wind_speed_gust", "node_id": "node_wind_gust", "param_key": "a", "not_in_model": false}]', '[{"outcome_key": "top_acceleration", "node_id": "node_top_accel", "port": "result", "reducer": "value", "threshold": 0.0}, {"outcome_key": "compressive