INSERT INTO audit_log (study_id, at, actor, action, entity, entity_id, details_json) SELECT 'std_02a4c5337c3442abb142', strftime('%Y-%m-%dT%H:%M:%S+00:00', 'now'), 'system', 'example_seeded', 'study', 'std_02a4c5337c3442abb142', '{"bundle": "example_studies", "version": 1}' WHERE NOT EXISTS (SELECT 1 FROM studies WHERE id = 'std_02a4c5337c3442abb142');
INSERT OR IGNORE INTO studies (id, name, description, domain, exclusion_threshold, confidence, cost_expression, budget, max_engine_evaluations, settings_json, rng_seed, archived, created_at, updated_at) VALUES ('std_02a4c5337c3442abb142', 'Hair Keratin Tribology & Cuticle Abrasion Wear (Transmissive Microscopy)', 'In-situ tribological wear screening of hair fiber cuticle scales under reciprocating micro-friction (Archard wear law: Δh = k·P·v·t). Simulates real-time surface smoothing, scale edge shearing, dynamic optical transmittance increase, and Abbe diffraction contrast drop as fibers rub together over 5.0 seconds. Example values — replace with your own.', 'biophysics_materials', 0.05, 0.95, '80 + 0.4 * normal_load_mn + 1.2 * sliding_velocity_mms', 5500.0, 50000, '{}', 888999, 0, '2026-10-29T08:43:26.421621+00:00', '2026-10-29T08:43:26.489235+00:00');
INSERT OR IGNORE INTO parameters (id, study_id, key, label, unit, kind, role, spec_json, position) VALUES ('par_d92c715288ce4228af4b', 'std_02a4c5337c3442abb142', 'normal_load_mn', 'Normal Contact Force', 'mN', 'continuous', 'controlled', '{"max":250.0,"min":50.0}', 1);
INSERT OR IGNORE INTO parameters (id, study_id, key, label, unit, kind, role, spec_json, position) VALUES ('par_c6c2e9f955034846bcf8', 'std_02a4c5337c3442abb142', 'sliding_velocity_mms', 'Reciprocating Rubbing Speed', 'mm/s', 'continuous', 'controlled', '{"max":20.0,"min":2.0}', 2);
