INSERT OR IGNORE INTO constraints (id, study_id, label, expression, kind, penalty, rationale, source_id, enabled, position) VALUES ('cst_8460a35dc4ac4037837f', 'std_02a4c5337c3442abb142', 'Catastrophic Cuticle Stripping Threshold', 'cuticle_wear_coeff <= 16.0', 'hard', NULL, 'High wear coefficient causes immediate scale edge delamination and total cuticle loss (illustrative)', NULL, 1, 1);
INSERT OR IGNORE INTO constraints (id, study_id, label, expression, kind, penalty, rationale, source_id, enabled, position) VALUES ('cst_bf66acbeadc24fd888bb', 'std_02a4c5337c3442abb142', 'Pre-damaged Fiber Rejection', 'initial_cuticle_thickness_um >= 2.5', 'hard', NULL, 'Fibers with less than 2.5 µm initial cuticle are pre-bleached/damaged and excluded from virgin wear benchmarks', NULL, 1, 2);
INSERT OR IGNORE INTO constraints (id, study_id, label, expression, kind, penalty, rationale, source_id, enabled, position) VALUES ('cst_2ab5284d292e45f6a5fd', 'std_02a4c5337c3442abb142', 'Gentle Combing Friction Preference', 'normal_load_mn <= 180.0', 'soft', 2.0, 'Loads above 180 mN represent harsh unconditioned brush snagging; lower loads reflect typical grooming', NULL, 1, 3);
INSERT OR IGNORE INTO model_versions (id, study_id, version, kind, project_json, parameter_bindings_json, outcome_bindings_json, engine_version, signature, validation_status, validation_json, notes, created_at) VALUES ('mod_3810704f086e496b83a1', 'std_02a4c5337c3442abb142', 1, 'flow', '{"version": 3, "name": "Hair Cuticle Friction Wear Simulation", "duration": 5.0, "sampleRate": 50.0, "nodes": [{"id": "n_stroke", "kind": "generator", "label": "Reciprocating Rubbing Stroke (mm)", "position": {"x": 40, "y": 160}, "params": {"wave": "triangle", "frequency": 1.0, "amplitude": 5.0, "offset": 0.0, "phase": 0.0, "unit": "mm"}}, {"id": "n_friction", "kind": "formula", "label": "Frictional Shear Force (mN)", "position": {"x": 340, "y": 60}, "params": {"expression": "120.0 * (0.35 + 0.06 * (a / 5.0) - 0.02 * t)", "a": 0.0, "b": 0.0, "unit": "mN"}}, {"id": "n_wear_thick", "kind": "formula", "label": "Cuticle Layer Thickness d(t) (\u00b5m)", "position": {"x": 340, "y": 220}, "params": {"expression": "max(18.0, 32.0 - 2.8 * t + 0.2 * (a / 5.0))", "a": 0.0, "b": 0.0, "unit": "\u00b5m"}}, {"id": "n_scale_frac", "kind": "formula", "label": "Cuticle Scale Roughness Fraction (%)", "position": {"x": 340, "y": 380}, "params": {"expression": "max(6.0, 36.0 - 5.8 * t + 1.5 * (a / 5.0))", "a": 0.0, "b": 0.0, "unit": "%"}}, {"id": "n_vibration", "kind": "formula", "label": "Stage Micro-Vibration \u0394z (\u00b5m)", "position": {"x": 340, "y": 540}, "params": {"expression": "0.35 * sin(2.0 * pi * 1.5 * t)", "a": 0.0, "b": 0.0, "unit": "\u00b5m"}}, {"id": "n_microscope", "kind": "transmissiveMicroscope", "label": "Transmissive Microscope", "position": {"x": 680, "y": 260}, "params": {"sourceMode": "Coupled Physical Inputs", "illuminationMode": "Brightfield", "magnification": 40.0, "numericalAperture": 0.65, "wavelengthNm": 546.0, "focusOffsetUm": 0.0, "immersionIndex": 1.0, "exposure": 1.0, "gridN": 64.0, "matrixThicknessUm": 32.0, "matrixAttenInvUm": 0.005, "featureAttenInvUm": 0.075, "matrixRefractiveIndex": 1.54, "featureRefractiveIndex": 1.51, "featureDiameterUm": 12.0, "featureVolumeFractionPct": 36.0, "chromophoreConcMolM3": 40.0, "molarAbsorptivityM2Mol": 0.15, "reticleFrequencyLpMm": 50.0, "seed": 777.0}}, {"id": "n_display", "kind": "microscopeDisplay", "label": "Real-Time Micrograph Viewport", "position": {"x": 1040, "y": 120}, "params": {}}, {"id": "n_scope_wear", "kind": "scope", "label": "Cuticle Wear & Friction Kinetics", "position": {"x": 1040, "y": 320}, "params": {}}, {"id": "n_scope_optical", "kind": "scope", "label": "Optical Centerline Transmission", "position": {"x": 1040, "y": 500}, "params": {}}], "edges": [{"id": "e_stroke_fric", "source": "n_stroke", "sourceHandle": "signal", "target": "n_friction", "targetHandle": "a"}, {"id": "e_stroke_thick", "source": "n_stroke", "sourceHandle": "signal", "target": "n_wear_thick", "targetHandle": "a"}, {"id": "e_stroke_frac", "source": "n_stroke", "sourceHandle": "signal", "target": "n_scale_frac", "targetHandle": "a"}, {"id": "e_thick_mic", "source": "n_wear_thick", "sourceHandle": "result", "target": "n_microscope", "targetHandle": "thickness"}, {"id": "e_frac_mic", "source": "n_scale_frac", "sourceHandle": "result", "target": "n_microscope", "targetHandle": "volumeFraction"}, {"id": "e_vib_mic", "source": "n_vibration", "sourceHandle": "result", "target": "n_microscope", "targetHandle": "focusOffset"}, {"id": "e_mic_disp", "source": "n_microscope", "sourceHandle": "micrograph", "target": "n_display", "targetHandle": "micrograph"}, {"id": "e_mic_scan", "source": "n_microscope", "sourceHandle": "lineProfile", "target": "n_scope_optical", "targetHandle": "ch1"}, {"id": "e_wear_scope", "source": "n_wear_thick", "sourceHandle": "result", "target": "n_scope_wear", "targetHandle": "ch1"}, {"id": "e_fric_scope", "source": "n_friction", "sourceHandle": "result", "target": "n_scope_wear", "targetHandle": "ch2"}], "tools": []}', '[{"parameter_key": "normal_load_mn", "node_id": null, "param_key": null, "not_in_model": true, "param_unit": null, "field_unit": null}, {"parameter_key": "sliding_velocity_mms", "node_id": null, "param_key": null, "not_in_model": true, "param_unit": null, "field_unit": null}, {"parameter_key": "cuticle_wear_coeff", "node_id": null, "param_key": null, "not_in_model": true, "param_unit": null, "field_unit": null}, {"parameter_key": "initial_cuticle_thickness_um", "node_id": null, "param_key": null, "not_in_model": true, "param_unit": null, "field_unit": null}, {"parameter_key": "vibration_amplitude_um", "node_id": null, "param_key": null, "not_in_model": true, "param_unit": null, "field_unit": null}, {"parameter_key": "objective_mag", "node_id": null, "param_key": null, "not_in_model": true, "param_unit": null, "field_unit": null}]', '[{"outcome_key": "transmittance_pct", "node_id": "n_microscope", "port": "transmittance", "reducer": "value", "threshold": 0.0}, {"outcome_key": "michelson_contrast", "node_id": "n_microscope", "port": "contrast", "reducer": "value", "threshold": 0.0}]', '2.2.0-2550a09', 'c81c0e31b9919f7c26940061d804a53647b826c0b509c5aecf8a3703c62cf30a', 'unvalidated', '{"model_id": "mod_3810704f086e496b83a1", "study_id": "std_02a4c5337c3442abb142", "evaluated_at": "2026-10-29T08:43:36.311948+00:00", "evidence_fingerprint": "5f2154d3389fb57c8c0d1ab70363fbeba31bf528eb0e043a9d6513f62b62c98c", "n_evidence_rows": 6, "min_required_rows": 8, "empirical_coverage_90": 0.0833, "target_coverage_90": 0.8, "rmse_by_outcome": {"transmittance_pct": 12.022255, "michelson_contrast": 0.05715}, "mae_by_outcome": {"transmittance_pct": 12.019667, "michelson_contrast": 0.047233}, "parity_points": [{"evidence_id": "evi_feafd1b110bb40248b4e", "outcome_key": "transmittance_pct", "measured": 68.0, "pred_mean": 80.253, "pi_low_90": 76.24035, "pi_high_90": 84.26565, "covered": false}, {"evidence_id": "evi_feafd1b110bb40248b4e", "outcome_key": "michelson_contrast", "measured": 0.45, "pred_mean": 0.4521, "pi_low_90": 0.429495, "pi_high_90": 0.474705,